// Bundle audit: attributes every generated byte of the entry chunk (or any chunk)
// to the source module it came from, using the build's source maps.
//
// Usage:
//   npx vite build --sourcemap=hidden --outDir dist-analyze
//   node scripts/analyze-bundle.mjs [dist-analyze] [chunk-name-substring] [top=25]
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { SourceMapConsumer } from 'source-map-js';

const [dir = 'dist-analyze', filter = null, topArg = '25'] = process.argv.slice(2);
const top = Number(topArg);
const assetsDir = join(dir, 'assets');
const html = readFileSync(join(dir, 'index.html'), 'utf8');
const entry = html.match(/src="\/assets\/([^"]+\.js)"/)?.[1];
const target = filter ? readdirSync(assetsDir).find((f) => f.includes(filter) && f.endsWith('.js')) : entry;
if (!target) throw new Error(`No chunk matching ${filter ?? 'entry'}`);

const code = readFileSync(join(assetsDir, target), 'utf8');
const map = JSON.parse(readFileSync(join(assetsDir, `${target}.map`), 'utf8'));
const consumer = new SourceMapConsumer(map);
const lines = code.split('\n');
const bytes = new Map();

// Walk mappings: each mapping owns the generated text up to the next mapping on the same line.
const mappings = [];
consumer.eachMapping((m) => mappings.push(m));
mappings.sort((a, b) => a.generatedLine - b.generatedLine || a.generatedColumn - b.generatedColumn);
for (let i = 0; i < mappings.length; i++) {
  const m = mappings[i];
  const next = mappings[i + 1];
  const lineText = lines[m.generatedLine - 1] ?? '';
  const end = next && next.generatedLine === m.generatedLine ? next.generatedColumn : lineText.length;
  const size = Math.max(0, end - m.generatedColumn);
  const source = m.source ?? '(unmapped)';
  bytes.set(source, (bytes.get(source) ?? 0) + size);
}

const byPackage = new Map();
for (const [source, size] of bytes) {
  const nm = source.lastIndexOf('node_modules/');
  let key;
  if (nm >= 0) {
    const rest = source.slice(nm + 'node_modules/'.length).split('/');
    key = rest[0].startsWith('@') ? `${rest[0]}/${rest[1]}` : rest[0];
  } else {
    key = source.replace(/^.*?\/src\//, 'src/').replace(/\/[^/]+$/, '/*');
  }
  byPackage.set(key, (byPackage.get(key) ?? 0) + size);
}

const total = code.length;
console.log(`${target}: ${(total / 1024).toFixed(1)} KB raw\n`);
for (const [key, size] of [...byPackage].sort((a, b) => b[1] - a[1]).slice(0, top)) {
  console.log(`${(size / 1024).toFixed(1).padStart(8)} KB  ${((size / total) * 100).toFixed(1).padStart(5)}%  ${key}`);
}
